Item.method_code:
if (!document.item) {
	return;
}

const { variables } = window.aras.getMainWindow().store.getState();
const isFipsMode = variables['fips_mode'];
if (isFipsMode) {
	Promise.all([
		ArasModules.cryptohash.SHA256(this.form.password.value),
		ArasModules.cryptohash.SHA256(this.form['confirm_password'].value)
	]).then(([passwordHash, confirmPasswordHash]) => {
		const oldVal = aras.getItemProperty(document.item, 'password');
		if (oldVal !== passwordHash) {
			aras.setItemProperty(document.item, 'password', passwordHash);
		}
		aras.setItemProperty(document.item, 'confirm_password', confirmPasswordHash);
	});
}

let encryptedFormValue = aras.calcMD5(this.form.password.value);
const oldVal = aras.getItemProperty(document.item, 'password');
if (oldVal !== encryptedFormValue) {
	aras.setItemProperty(document.item, 'password', encryptedFormValue);
}
encryptedFormValue = aras.calcMD5(this.form['confirm_password'].value);
aras.setItemProperty(document.item, 'confirm_password', encryptedFormValue);
